7. ### Request
8. 
9. ```ts
10. type CopilotClarifyRequest = {
11.   subscriptionId: string;
12.   repositoryPath: string;
13.   branch: string;
14.   sessionId?: string;
15.   mode: 'next' | 'askAnother' | 'reaskMalformed' | 'commit';
16.   questionId?: string;
17.   answers?: Array<{ questionId: string; choiceKey: string; note?: string }>;
18.   reaskContext?: {
19.     malformedQuestionText: string;
20.     position: number;
21.     malformationCategory: string;
22.     wellFormedQuestions: Array<{ id: string; text: string }>;
23.   };
24.   modelId?: string;
25. };
26. ```
